const i=new Intl.NumberFormat("vi-VN"),f=new Intl.NumberFormat("vi-VN",{maximumFractionDigits:1}),g=t=>t==null?"×—":`×${f.format(t)}`,$=t=>t==null?"—":f.format(t);function l(t){return t==null?"—":t>=1e6?`${f.format(t/1e6)} Tr`:t>=1e4?`${i.format(Math.round(t/1e3))} N`:i.format(t)}function h(t){return t==null?"—":t>=1e6?`${(Math.round(t/1e4)/100).toLocaleString("vi-VN",{maximumFractionDigits:2})} Tr`:t>=1e3?`${i.format(Math.round(t/1e3))} N`:i.format(t)}function c(t,e=Date.now()){if(!t)return"";const r=new Date(t).getTime();if(Number.isNaN(r))return"";const n=(e-r)/36e5;if(n<1)return"mới đăng";if(n<24)return`${Math.floor(n)} giờ`;const a=Math.floor(n/24);if(a<14)return`${a} ngày`;const o=Math.floor(a/7);if(o<13)return`${o} tuần`;const s=new Date(r),m=u=>String(u).padStart(2,"0");return`${m(s.getDate())}/${m(s.getMonth()+1)}`}const M=t=>{if(t==null)return"";const e=Math.max(0,Math.floor(t)),r=Math.floor(e/3600),n=Math.floor(e%3600/60),a=e%60,o=r>0?String(n).padStart(2,"0"):String(n);return`${r>0?`${r}:`:""}${o}:${String(a).padStart(2,"0")}`};function d(t,e){const r=t==null?"":`${l(t)} lượt xem`,n=c(e);return[r,n].filter(Boolean).join(" · ")}export{g as a,h as b,c,M as f,$ as s,d as v};
